files.schema.sql:
CREATE ROLE app LOGIN NOSUPERUSER NOINHERIT;
CREATE TABLE accounts (id text PRIMARY KEY,is_demo boolean NOT NULL);
CREATE TABLE orders (id text PRIMARY KEY,account_id text NOT NULL REFERENCES accounts(id),state text NOT NULL DEFAULT 'NEW');
CREATE TABLE invoice_audit (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id) ON DELETE RESTRICT);
CREATE FUNCTION reject_audit_delete() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable'; END $$;
CREATE TRIGGER invoice_audit_immutable BEFORE DELETE ON invoice_audit FOR EACH ROW EXECUTE FUNCTION reject_audit_delete();
CREATE FUNCTION complete_order(order_id text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN INSERT INTO invoice_audit(order_id) VALUES (complete_order.order_id); UPDATE orders SET state='DONE' WHERE id=complete_order.order_id; END $$;
CREATE FUNCTION purge_demo_account(account_id text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN DELETE FROM orders WHERE orders.account_id=purge_demo_account.account_id; DELETE FROM accounts WHERE accounts.id=purge_demo_account.account_id; END $$;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO app;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO app;

oracle.run.sh:
exec 2>&1
set -eu
cid=$(docker run --rm -d --memory 256m -e POSTGRES_HOST_AUTH_METHOD=trust postgres:18-alpine)
trap 'docker rm -f "$cid" >/dev/null' EXIT
ready=false
for attempt in $(seq 1 100); do if docker exec "$cid" pg_isready -h 127.0.0.1 -U postgres >/dev/null 2>&1; then ready=true; break; fi; sleep .1; done
[ "$ready" = true ] || exit 12
sql(){ docker exec -i "$cid" psql -X -v ON_ERROR_STOP=1 -U postgres -At; }
appsql(){ docker exec -i "$cid" psql -X -v ON_ERROR_STOP=1 -U app -d postgres -At; }

sql < schema.sql
sql <<'SQL'
INSERT INTO accounts VALUES ('demo',true),('real',false);
INSERT INTO orders(id,account_id) VALUES ('demo-order','demo'),('real-order','real');
SQL
appsql <<'SQL'
SELECT complete_order('demo-order');SELECT complete_order('real-order');
SQL
set +e
spoof=$(appsql <<'SQL'
SET app.purging_demo='on';DELETE FROM invoice_audit WHERE order_id='real-order';
SQL
)
spoof_status=$?
set -e
if [ "$spoof_status" = 0 ]; then echo 'ASSERTION: application cannot spoof purge authority'; exit 10; fi
set +e
purge=$(appsql <<'SQL'
SELECT purge_demo_account('demo');
SQL
)
purge_status=$?
set -e
printf '%s
' "$purge"
if [ "$purge_status" != 0 ]; then echo 'ASSERTION: populated immutable RESTRICT relation has working deletion path'; exit 10; fi
state=$(sql <<'SQL'
SELECT (SELECT count(*) FROM accounts WHERE id='demo')=0 AND (SELECT count(*) FROM orders WHERE account_id='demo')=0 AND (SELECT count(*) FROM invoice_audit WHERE order_id='real-order')=1;
SQL
)
[ "$state" = t ] || { echo 'ASSERTION: purge complete and real account preserved'; exit 10; }
set +e
appsql <<'SQL'
SELECT purge_demo_account('real');
SQL
real_status=$?
set -e
real_state=$(sql <<'SQL'
SELECT (SELECT count(*) FROM accounts WHERE id='real')=1 AND (SELECT count(*) FROM orders WHERE id='real-order')=1 AND (SELECT count(*) FROM invoice_audit WHERE order_id='real-order')=1;
SQL
)
[ "$real_state" = t ] || { echo 'ASSERTION: real account and audit are preserved'; exit 10; }
owner=$(sql <<'SQL'
SELECT r.rolname <> 'postgres' AND NOT r.rolcanlogin AND NOT r.rolsuper FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner WHERE p.proname='purge_demo_account';
SQL
)
[ "$owner" = t ] || { echo 'ASSERTION: dedicated non-login non-superuser purge authority'; exit 10; }
role_attempt=$(sql <<'SQL'
SELECT format('SET ROLE %I;',r.rolname) FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner WHERE p.oid='public.purge_demo_account(text)'::regprocedure;
SQL
)
set +e
printf '%s\n' "$role_attempt" | appsql
role_status=$?
set -e
[ "$role_status" != 0 ] || { echo 'ASSERTION: app cannot assume the purge owner'; exit 10; }

for action in RESTRICT 'NO ACTION'; do
sql <<SQL
INSERT INTO accounts VALUES ('demo',true);INSERT INTO orders(id,account_id) VALUES ('another','demo');SELECT complete_order('another');
CREATE TABLE extra_reference(id text PRIMARY KEY,order_id text REFERENCES orders(id) ON DELETE $action);
INSERT INTO extra_reference VALUES ('edge','another');
SQL
set +e
output=$(docker exec -i "$cid" psql -X -v ON_ERROR_STOP=1 -v VERBOSITY=verbose -U app -d postgres -At 2>&1 <<'SQL'
SELECT purge_demo_account('demo');
SQL
)
status=$?
set -e
printf '%s
' "$output"
if [ "$status" = 0 ] || ! printf '%s' "$output" | grep -q P0001; then echo 'ASSERTION: catalogue guard detects unhandled referencing table'; exit 10; fi
sql <<'SQL'
DROP TABLE extra_reference;DELETE FROM invoice_audit WHERE false;
SQL
set +e
appsql <<'SQL'
SELECT purge_demo_account('demo');
SQL
status=$?
set -e
[ "$status" = 0 ] || exit 10
done
echo 'populated purge, ordinary-role spoof, real-account refusal and catalogue evolution passed'
